INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Changing Ireland in a time of Coronavirus – Three books to read', 'editor-changingireland-allen-in-a-time-of-coronavirus', '<p><iframe title="Changing Ireland in a time of Coronavirus - Three books to read" width="696" height="522" src="https://www.youtube.com/embed/jckTZG5ulLw?feature=oembed" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></p>
<p>This is the first broadcast by <em>Changing Ireland</em> since a microscopic virus changed the way many people live. It is the first in a series and, between difficult times, we will bring you news from communities and the community sector in Ireland and provide encouragement.</p>
<p>Here, I suggest three great books to read. In the video, a family member also makes a star appearance half-way through to tell you about the magazine I love most. Yes, you&#8217;ve guessed it&#8230;</p>
<p>Right now, we have 5,000 copies of our Spring edition to distribute. All libraries and many places we post to are closed, but we&#8217;ll get &#8216;Changing Ireland&#8217; to you in print and/or online.</p>
<p><img fetchpriority="high" decoding="async" src="https://changingireland.ie/wp-content/uploads/2020/03/ISS-68-SPRING-2020-COVER.png" alt="" width="634" height="890" srcset="https://changingireland.ie/wp-content/uploads/2020/03/ISS-68-SPRING-2020-COVER.png 634w, https://changingireland.ie/wp-content/uploads/2020/03/ISS-68-SPRING-2020-COVER-214x300.png 214w" sizes="(max-width: 634px) 100vw, 634px" /></p>
<p>We were also talking to Easons about expanding distribution through Centra and Spar stores, etc. A further update on this will follow.</p>
<p>My three book recommendations are:<br />
&#8211; ‘THE ENTERPRISING COMMUNITY’ By Dr. Senan Cooke.<br />
&#8211; &#8216;LIFE, DEATH AND HURLING&#8217; by Michael Duignan.<br />
&#8211; &#8216;THE BOY WHO WANTED TO FLY&#8217; by Don Mullan.</p>
<p>Best regards &#8211; Allen, editor.</p>', 'We’re one week down. Listen to editor Allen Meagher’s take on the changed landscape.', 'https://changingireland.ie/wp-content/uploads/2020/03/Screen-Shot-3.png', '', '[{"slug":"activism-volunteering","title":"Activism & Volunteering"},{"slug":"community","title":"Community"},{"slug":"editors-picks","title":"Editor''s Picks"}]', '[{"slug":"changingireland","title":"#ChangingIreland"},{"slug":"communityresponseirl","title":"#CommunityResponseIRL"},{"slug":"community-resilience","title":"Community resilience"},{"slug":"senan-cooke","title":"Senan Cooke"},{"slug":"social-enterprise","title":"social enterprise"}]', '', 248936, 1, '2020-03-20T18:20:36Z', '2020-03-23T19:53:26Z', '2020-03-20T18:20:36Z')
