INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Jim Finn is new chairperson of the Irish Local Development Network', 'irish-local-development-network-new-chairperson', '<p><b>Irish Local Development Network</b></p>
<p><span>NEW CHAIRPERSON</span></p>
<p><span>Jim Finn from Ballinahow, Co. Tipperary, has been appointed chairperson of the Irish Local Development Network, the representative body for the country’s 49 Local Development Companies.</span></p>
<p><span>In a voluntary capacity, Jim already serves as chairperson of North Tipperary Development Company and broadcasts extensively on community and rural affairs for Tipp FM. He takes over from Marie Price Bolger who led the network from 2015. </span></p>
<p><span>The country’s Local Development Companies deliver social and community supports services such as LEADER, Local Employment Services, the Social Inclusion and Community Activation Programme, Tús, the Rural Social Scheme, social enterprise supports and a range of other community and rural development programmes.</span></p>
<p><span>On becoming chair, Jim said, “there have been many positive, recent policy developments such as the publication of a national Social Enterprise Policy and the new 5-year Strategy for the Community and Voluntary Sector. But, many of our communities and disadvantaged groups are still reeling from the impact of disproportionate cuts over the past decade.”</span></p>
<p><span>His key priorities for the sector include securing:</span></p>
<p><span>&#8211; An increase in social inclusion funding, </span></p>
<p><span>&#8211; Protection and extension of community-based employment services, </span></p>
<p><span>&#8211; Adequate resourcing and simplified design of rural funds, eg LEADER. </span></p>
<p><span>He said the “bottom-up community engagement approach of Local Development Companies” was particularly suited to the climate action challenge.</span></p>
<p><span>He called for “consistent core-funding” for Local Development Companies who are “the primary delivery agent of much of the state’s response to unemployment and social exclusion”. </span></p>
<p><span>“I am also particularly conscious that our companies are governed by volunteer-led boards and I look forward to the full implementation of the ‘Sustainable, Inclusive and Empowered Communities’ strategy with appropriate supports for the voluntary, bottom-up approach that is so vital for our communities.” </span></p>
<p><span>Regarding the ILDNs value, Jim said it was the largest network of companies in the State for community development and anti-poverty work: “We have over 2,100 employees and 9,500 Tús &amp; RSS workers on the ground supporting over 15,000 community groups and 173,000 individuals annually through €300+ million of state-funded programmes.”</span></p>
<h1><span>Passionate predecessor, Marie Price-Bolger, made her mark<br />
</span></h1>
<figure aria-describedby="caption-attachment-249851"><img decoding="async" src="https://changingireland.ie/wp-content/uploads/2020/03/Marie-Price-Bolger-scaled-e1595595763972.jpg" alt="Marie Price Bolger" width="1817" height="1312" srcset="https://changingireland.ie/wp-content/uploads/2020/03/Marie-Price-Bolger-scaled-e1595595763972.jpg 1817w, https://changingireland.ie/wp-content/uploads/2020/03/Marie-Price-Bolger-scaled-e1595595763972-300x217.jpg 300w, https://changingireland.ie/wp-content/uploads/2020/03/Marie-Price-Bolger-scaled-e1595595763972-1024x739.jpg 1024w, https://changingireland.ie/wp-content/uploads/2020/03/Marie-Price-Bolger-scaled-e1595595763972-768x555.jpg 768w, https://changingireland.ie/wp-content/uploads/2020/03/Marie-Price-Bolger-scaled-e1595595763972-1536x1109.jpg 1536w, https://changingireland.ie/wp-content/uploads/2020/03/Marie-Price-Bolger-scaled-e1595595763972-1080x780.jpg 1080w" sizes="(max-width: 1817px) 100vw, 1817px" /><figcaption><em>Marie Price Bolger</em></figcaption></figure>
<p><span>He paid tribute to his predecessor Marie Price-Bolger: “She led the network through a period of very significant funding and policy challenges. She served the organisation and the sector with great dedication, energy and fairness.”</span></p>
<p><span>Marie made a speech last year calling on the Government to look beyond private sector suppliers, stressing that it is volunteers who make communities work. She said, “Our sector consistently provides services on behalf of government departments in an efficient, effective and value for money model that cannot be matched by any private-sector programme.”</span></p>
<p><span>Directly addressing Minister for Rural and Community Development Michael Ring, who was in attendance, Price-Bolger asked him to bring to cabinet concerns about the privatisation of community work.*</span></p>
<p><i><span>* Our 2019 report: <a href="https://changingireland.ie/volunteers-make-communities-work-sdcp-ildn-price-bolger/">https://changingireland.ie/volunteers-make-communities-work-sdcp-ildn-price-bolger/</a></span></i></p>
<p>&nbsp;</p>', '“Many of our communities and disadvantaged groups are still reeling from the impact of disproportionate cuts over the past decade.” – Jim Finn', 'https://changingireland.ie/wp-content/uploads/2020/07/Jim-Finn-ILDN.jpg', 'Jim Finn Jim Finn is the new chairperson of the Irish Local Development Network.', '[{"slug":"community","title":"Community"},{"slug":"planning-governance","title":"Planning & Governance"}]', '[{"slug":"community-development","title":"community development"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"irish-local-development-network-ildn","title":"Irish Local Development Network"},{"slug":"social-enterprise","title":"social enterprise"}]', '', 249828, 1, '2020-03-14T13:54:29Z', '2020-07-28T15:15:09Z', '2020-03-14T13:54:29Z')
