INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('INSPIRE A NATION: Awesome People – Brigid Quilligan Community worker & activist', 'inspire-a-nation-awesome-people-brigid-quilligan-community-worker-activist', '<p><strong>What’s the last film you saw?</strong><br />
‘Fight Like a Butterfly’.</p>
<p><strong>Person you most admire?</strong><br />
My mother.</p>
<p><strong>The top four issues in Ireland today?</strong><br />
1. Racism.<br />
2. Mental health of Travellers.<br />
3. Lack of autism services.<br />
4. Classism.</p>
<p><strong>Nationally, we need more…</strong><br />
&#8230;Diversity in politics &#8211; meaning representation from people with different ethnicities and backgrounds.<br />
And devolve all local Traveller accommodation powers to one national agency.<br />
I strongly believe we need a State apology for the treatment of Travellers by the State; an acknowledgement of what that treatment was.<br />
Then we need a peace and reconciliation process within the community.</p>
<p><strong>Nationally, we need less&#8230;</strong><br />
…Parish-pump politics.</p>
<p><strong>What’s the best thing about the project you volunteer with?</strong><br />
The solidarity here at Kerry Travellers’ Health Community Development Project and the common purpose of our team and volunteers. We all are passionate about human rights.</p>
<p><strong>What could your project improve on doing?</strong><br />
Promoting our work and reaching families we currently do not work with.</p>
<p><strong>How long are you volunteering?</strong><br />
I have volunteered with community groups and campaigns for 30 years.</p>
<p><strong>How and why did you get involved?</strong><br />
I realised that if change is going to come, those afflicted by oppression have to be the ones to demand it.</p>
<p><strong>What difference has being involved made to you?</strong><br />
It has influenced my life and exposed me to different communities.</p>
<p><strong>Have things changed for your community since you became involved?</strong><br />
Traveller ethnicity is now recognised.<br />
We have a stronger Traveller voice.<br />
The recognition by UNESCO of Traveller language &#8211; Gammon &#8211; in July was a momentous achievement.<br />
More young people are in education.</p>
<p><strong>What motivates you as a volunteer?</strong><br />
I see too many young people from my community dying. We need to change policy, practice and legislation so that it includes and is led by the marginalised.<br />
I love to see young people reaching their full potential and developing their skills and enterprise.</p>
<p><strong>What inspires you?</strong><br />
Our youth is a very inspiring group; the discrimination that they face is much worse than the discrimination their parents faced. They are subjected to anti-Travellerism on social media, in schools and shops, when accessing services. They are constantly made to justify their existence as Travellers.<br />
They are bright, educated, articulate, and they will be the ones to create a new Ireland.</p>
<p><strong>How do you get new volunteers?</strong><br />
By telling our truthful story. We are credible. We know and love our community &#8211; that inspires people.</p>
<p><strong>What brings about change?</strong><br />
People say they want change, but they do nothing to create that change; we collude in our own oppression. Civil rights are being impacted on every day, so why are we so silent? Change can only come when communities come together.</p>
<h4>
Quilligan on Twitter: @BrigidQuilligan</h4>
<h4>Nominate a volunteer!<br />
If you wish to nominate a volunteer, activist or otherwise remarkable person, email: editor@changingireland.ie</h4>', 'What motivates you as a volunteer? I see too many young people from my community dying. We need to change policy, practice and legislation so that it includes and is led by the marginalised.', 'https://changingireland.ie/wp-content/uploads/2020/11/IMG_4871-rotated.jpg', '', '[{"slug":"activism-volunteering","title":"Activism & Volunteering"},{"slug":"equality-rights","title":"Equality & Rights"},{"slug":"people","title":"People"}]', '[{"slug":"activism","title":"activism"},{"slug":"collective-action","title":"Collective Action"},{"slug":"irish-traveller-movement","title":"Irish Traveller Movement"},{"slug":"travellers","title":"Travellers"},{"slug":"youth-work","title":"youth work"}]', '', 250072, 1, '2019-10-16T09:00:15Z', '2020-11-20T10:42:29Z', '2019-10-16T09:00:15Z')
