INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Helping Hands: Communities out in force for funding advice', 'helping-hands-funding-grants-advice', '<p>During April and May, six Helping Hands information sessions were held to give tips to volunteers seeking funds for their local community projects. The first was held in Ballina, Co Mayo, on 25 April.</p>
<p>Minister for Rural and Community Development (and Mayo TD) Michael Ring has often expressed his exasperation at the paperwork involved in securing funding. He was on hand to launch the Ballina event.</p>
<figure aria-describedby="caption-attachment-247219"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2019/08/67248472_10157512517084357_2161919067441594368_o-300x200.jpg" alt="Minister Ring pictured at Ballina event" width="600" height="400" srcset="https://changingireland.ie/wp-content/uploads/2019/08/67248472_10157512517084357_2161919067441594368_o-300x200.jpg 300w, https://changingireland.ie/wp-content/uploads/2019/08/67248472_10157512517084357_2161919067441594368_o-768x512.jpg 768w, https://changingireland.ie/wp-content/uploads/2019/08/67248472_10157512517084357_2161919067441594368_o-1024x683.jpg 1024w, https://changingireland.ie/wp-content/uploads/2019/08/67248472_10157512517084357_2161919067441594368_o.jpg 1080w" sizes="(max-width: 600px) 100vw, 600px" /><figcaption><em>Minister Michael Ring pictured at the Helping Hands event. Photo: Allen Meagher.</em></figcaption></figure>
<p>The events were aimed at community groups that have previously had no success or limited success applying for funding, but all were welcome to attend.</p>
<p>Sessions gave advice on how to make a better application and how to identify local supports that community groups can draw on, including funds people might not know existed. Attendees were also able to meet key staff, make contacts and engage in one-on-one discussions.</p>
<p>The five other events took place in counties Donegal, Cork, Limerick, Tullamore and Coolock. They were run by the <a href="https://drcd.gov.ie" target="_blank" rel="noopener noreferrer">Department of Rural and Community Development</a>, <a href="https://pobal.ie" target="_blank" rel="noopener noreferrer">Pobal</a>, local authorities, the <a href="https://ildn.ie" target="_blank" rel="noopener noreferrer">Irish Local Development Network</a> and local development companies.</p>
<p>If you weren’t fortunate enough to attend, Helping Hands guides are available for download <a href="https://www.pobal.ie/app/uploads/2019/04/Pobal-Brochure-1-Planning-an-Application-web.pdf?fbclid=IwAR2DxWXUxPQNvbXaBGeorSj3DwkhMpWDiAIZ6kuCh94rOivTT_n5_6vEr7I" target="_blank" rel="noopener noreferrer">here</a> and <a href="https://www.pobal.ie/app/uploads/2019/04/Pobal-Brochure-2-Writing-an-Application-web.pdf?fbclid=IwAR3qcSkXt0KVbla3LjpcwJMdz7c4UlqRTXFDdyHgzcslEHoCUJVFMmIRyxg" target="_blank" rel="noopener noreferrer">here</a>.</p>
<h4><strong>Some volunteers still chasing funding after 40 years</strong></h4>
<p>If you could shoot 40 years into the future, would you meet the same people volunteering as you do now? Most likely.</p>
<p>Would they still be wondering where to get funding to keep the show on the road? Yes.</p>
<p>My family moved to Ballina around the time the pope visited Ireland, in 1979. I lived there as a kid for two years and loved it. I was in the <a href="https://scouts.ie" target="_blank" rel="noopener noreferrer">Scouts</a> and played tennis and rugby. (Thanks, of course, to the adults who volunteered in these clubs and groups.)</p>
<figure aria-describedby="caption-attachment-247220"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2019/08/67170761_10157512520844357_2710394117786959872_n-262x300.jpg" alt="Benny Walkin" width="400" height="458" srcset="https://changingireland.ie/wp-content/uploads/2019/08/67170761_10157512520844357_2710394117786959872_n-262x300.jpg 262w, https://changingireland.ie/wp-content/uploads/2019/08/67170761_10157512520844357_2710394117786959872_n.jpg 720w" sizes="(max-width: 400px) 100vw, 400px" /><figcaption><em>Benny Walkin pictured at an event celebrating his 48 years with the Scouts.</em></figcaption></figure>
<p>On 25 April 2019, as I strolled into Helping Hands, I didn’t think I’d make connections from way back in my youth.</p>
<p>I met a Scout leader going in.</p>
<p>“Did you have Benny Walkin?” he asked.</p>
<p>“I did. He’s hardly still involved?” I said.</p>
<p>“He is. Still going strong.”</p>
<p>I was astonished. That meant that Benny had given over 40 years of volunteering to the Scouts.</p>
<p>Inside, I met Vincent Frawley, who had come to live in Ballina in 1978, a year before my family moved there. I remember taking tennis lessons one summer. Vincent may well have been one of my coaches. He’s still involved.</p>
<p>From 1979 to 1981, we liked to drive out to Lacken to see the unspoiled beauty and play on the beach.</p>
<p>A woman from Lacken had driven in – on her one night off from being her husband’s carer – to pick up tips. She’s been volunteering for 25 years with Lacken Community Care and other groups. Over 60% of the population in her area now consists of older people, and they need to find out what grants are there to support their community.</p>
<p>The draw of superb information evenings such as the one in Ballina is that they connect fantastic groups with grant schemes they might not otherwise know about. They aim to help people to identify local supports that community groups can draw upon.</p>
<p>Just one of many tips given: “Don’t lower your chances by using old data when your population might have grown. Use the latest CSO figures.”</p>
<p><strong><em>Interested in reading more about the state of Ireland’s community development sector? Check out our </em></strong><a href="https://bit.ly/Iss64-May" target="_blank" rel="noopener noreferrer"><strong><em>latest issue</em></strong></a><strong><em>.</em></strong></p>', 'Many community organisations rely on funding to keep the lights on, but grant application processes can be overly complex. What if there were information sessions to help with that?', 'https://changingireland.ie/wp-content/uploads/2019/08/IMG_1198.jpg', 'Crowd gathered at Mayo Helping Hands seminar', '[{"slug":"grants-subsidies","title":"Grants & Subsidies"}]', '[{"slug":"advice","title":"advice"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"funding","title":"funding"},{"slug":"mayo","title":"Mayo"},{"slug":"michael-ring","title":"Michael Ring"},{"slug":"pobal","title":"Pobal"}]', '', 247208, 1, '2019-07-23T13:14:53Z', '2019-09-17T12:05:19Z', '2019-07-23T13:14:53Z')
