INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('SICAP report calls for bottom-up approach to evaluation', 'sicap-report-evaluation-esri', '<p>‘<a href="https://www.esri.ie/publications/valuing-community-development-through-the-social-inclusion-programme-sicap-2015-2017" target="_blank" rel="nofollow noopener noreferrer">Valuing community development through the social inclusion programme (SICAP) 2015–2017: Toward a framework for evaluation</a>’, a new 108-page report on SICAP released in February, sheds light on whether community development can be evaluated and aims to determine how that evaluation could feasibly be carried out.</p>
<p>Based on extensive research and a series of consultation workshops, the Economic and Social Research Institute (<a href="https://www.esri.ie/" target="_blank" rel="nofollow noopener noreferrer">ESRI</a>) report concludes that evaluation of SICAP-supported initiatives is challenging not least because most communities draw on multiple funding sources, making it difficult to isolate impact from one particular income stream.</p>
<p>Nevertheless, the report detailed “a strong willingness on the part of [local community workers], members of [local community groups] and other key policy stakeholders to implement methods that are appropriate both for the interests of marginalised communities and groups, and for the needs of the state and other funders”.</p>
<p>A number of solutions were suggested:</p>
<p>• generating a framework that would focus on the capacity of local groups to influence change on a community level;</p>
<p>• the introduction of self-assessment through a distance-travelled tool similar to that used by <a href="https://pobal.ie" target="_blank" rel="nofollow noopener noreferrer">Pobal</a>;</p>
<p>• drawing good practice approaches from analysis of thematic reports, and focusing on the specifics impacts of funding on particular target groups.</p>
<p>According to the report, “such qualitative approaches allow for a more systematic and in-depth analysis of the impact of SICAP on community-level outcomes”.</p>
<p>The report was funded by the <a href="https://drcd.gov.ie" target="_blank" rel="nofollow noopener noreferrer">Department of Rural and Community Development</a> and carried out by the ESRI. It was written by Adele Whelan, Seamus McGuinness and Judith Delaney.</p>
<p><strong><em>Interested in reading more about the state of Ireland’s community development sector? Check out our </em></strong><a href="https://bit.ly/Iss64-May" target="_blank" rel="nofollow noopener noreferrer"><strong><em>latest issue</em></strong></a><strong><em>.</em></strong></p>
